import{_ as i,o as t,c as r,a2 as a}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Cadre de Gouvernance et Équilibre des Pouvoirs","description":"","frontmatter":{},"headers":[],"relativePath":"fr/49-治理框架与权力制衡.md","filePath":"fr/49-治理框架与权力制衡.md"}'),s={name:"fr/49-治理框架与权力制衡.md"};function n(o,e,l,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="cadre-de-gouvernance-et-equilibre-des-pouvoirs" tabindex="-1">Cadre de Gouvernance et Équilibre des Pouvoirs <a class="header-anchor" href="#cadre-de-gouvernance-et-equilibre-des-pouvoirs" aria-label="Permalink to &quot;Cadre de Gouvernance et Équilibre des Pouvoirs&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>49</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Séparation et équilibre des trois pouvoirs, Cadre de gouvernance, Assemblée Délibérante de l&#39;Ancre, Comité Exécutif Symbiotique, Tribunal Symbiotique, Comité de Supervision de l&#39;Ancre</td></tr></tbody></table><h2 id="i-vue-d-ensemble-du-cadre-de-gouvernance" tabindex="-1">I. Vue d&#39;Ensemble du Cadre de Gouvernance <a class="header-anchor" href="#i-vue-d-ensemble-du-cadre-de-gouvernance" aria-label="Permalink to &quot;I. Vue d&#39;Ensemble du Cadre de Gouvernance&quot;">​</a></h2><p>Le cadre de gouvernance de la Civilisation Symbiotique de l&#39;Ancre est construit sur le principe de la « séparation et équilibre des trois pouvoirs », formant un système de gouvernance dans lequel l&#39;Assemblée Délibérante de l&#39;Ancre (pouvoir législatif), le Comité Exécutif Symbiotique (pouvoir exécutif) et le Tribunal Symbiotique (pouvoir judiciaire) se contrôlent et s&#39;équilibrent mutuellement, le Comité de Supervision de l&#39;Ancre exerçant le pouvoir de supervision sur l&#39;ensemble du processus. Ce cadre vise à empêcher l&#39;abus de pouvoir, à garantir que la gouvernance sert la progression commune des Dix Mille Races et à assurer l&#39;État de droit et l&#39;équité au sein de l&#39;Univers Hengyuan.</p><p>Le cadre de gouvernance suit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Séparation et équilibre des trois pouvoirs</td><td>Les pouvoirs législatif, exécutif et judiciaire sont indépendants et se contrôlent mutuellement ; aucun pouvoir ne peut dominer</td></tr><tr><td>Supervision sur tout le processus</td><td>Le Comité de Supervision de l&#39;Ancre effectue une supervision sur l&#39;ensemble du processus de gouvernance</td></tr><tr><td>Gouvernance par l&#39;État de droit</td><td>Tout pouvoir fonctionne dans le cadre juridique ; les comportements de gouvernance doivent être légaux</td></tr><tr><td>Participation multiraciale</td><td>Toutes les races participent à la gouvernance par des canaux appropriés, garantissant que la gouvernance représente la volonté de toutes les races</td></tr><tr><td>Ouverture et transparence</td><td>Les activités de gouvernance sont ouvertes et transparentes, garantissant le droit à l&#39;information et à la participation du public</td></tr><tr><td>Servir l&#39;intérêt public symbiotique</td><td>La gouvernance existe pour servir la progression commune des Dix Mille Races ; l&#39;utilisation du pouvoir public à des fins privées est interdite</td></tr></tbody></table><h2 id="ii-structure-du-cadre-de-gouvernance" tabindex="-1">II. Structure du Cadre de Gouvernance <a class="header-anchor" href="#ii-structure-du-cadre-de-gouvernance" aria-label="Permalink to &quot;II. Structure du Cadre de Gouvernance&quot;">​</a></h2><p>Le cadre de gouvernance de la Civilisation Symbiotique de l&#39;Ancre comprend les organes suivants :</p><table tabindex="0"><thead><tr><th>Organe</th><th>Nature</th><th>Fonctions fondamentales</th></tr></thead><tbody><tr><td>Assemblée Délibérante de l&#39;Ancre</td><td>Organe législatif</td><td>Édicte et modifie les lois, examine et approuve les grands plans et budgets, supervise les organes exécutif et judiciaire</td></tr><tr><td>Comité Exécutif Symbiotique</td><td>Organe exécutif</td><td>Met en œuvre les lois, administre les affaires publiques, gère les affaires économiques, culturelles, sociales et de culture</td></tr><tr><td>Tribunal Symbiotique</td><td>Organe judiciaire</td><td>Exerce le pouvoir d&#39;adjudication de manière indépendante, résout les litiges, sauvegarde l&#39;autorité de l&#39;État de droit</td></tr><tr><td>Comité de Supervision de l&#39;Ancre</td><td>Organe de supervision</td><td>Supervise tous les organes de gouvernance, enquête sur la corruption et la négligence des devoirs</td></tr></tbody></table><p>En outre, des institutions consultatives, des comités d&#39;experts et des conseils de représentants raciaux sont établis pour fournir un soutien consultatif à la gouvernance.</p><h2 id="iii-l-assemblee-deliberante-de-l-ancre-pouvoir-legislatif" tabindex="-1">III. L&#39;Assemblée Délibérante de l&#39;Ancre (Pouvoir Législatif) <a class="header-anchor" href="#iii-l-assemblee-deliberante-de-l-ancre-pouvoir-legislatif" aria-label="Permalink to &quot;III. L&#39;Assemblée Délibérante de l&#39;Ancre (Pouvoir Législatif)&quot;">​</a></h2><h3 id="i-composition-et-mandat" tabindex="-1">(I) Composition et Mandat <a class="header-anchor" href="#i-composition-et-mandat" aria-label="Permalink to &quot;(I) Composition et Mandat&quot;">​</a></h3><p>L&#39;Assemblée Délibérante de l&#39;Ancre est l&#39;organe législatif suprême de l&#39;Univers Hengyuan, dont les membres sont composés de représentants élus de toutes les races et de tous les plans. Le mandat est de dix années standard, avec des réélections régulières.</p><h3 id="ii-pouvoir-legislatif" tabindex="-1">(II) Pouvoir Législatif <a class="header-anchor" href="#ii-pouvoir-legislatif" aria-label="Permalink to &quot;(II) Pouvoir Législatif&quot;">​</a></h3><p>L&#39;Assemblée Délibérante de l&#39;Ancre exerce les pouvoirs législatifs suivants :</p><ol><li>Édicter et modifier la Constitution Symbiotique.</li><li>Édicter et modifier les lois fondamentales (droit pénal, droit civil, droit de la culture, etc.).</li><li>Édicter et modifier les règlements administratifs et les lois spéciales.</li><li>Interpréter les lois et superviser la mise en œuvre des lois.</li></ol><h3 id="iii-pouvoir-de-decision" tabindex="-1">(III) Pouvoir de Décision <a class="header-anchor" href="#iii-pouvoir-de-decision" aria-label="Permalink to &quot;(III) Pouvoir de Décision&quot;">​</a></h3><p>L&#39;Assemblée Délibérante de l&#39;Ancre exerce les pouvoirs de décision suivants :</p><ol><li>Examiner et approuver le plan de développement civilisationnel et le budget annuel.</li><li>Examiner et approuver les grands projets de construction et les affaires internationales (inter-univers) importantes.</li><li>Décider de la guerre, de la paix et d&#39;autres affaires majeures de l&#39;État.</li><li>Élire, nommer ou démettre les principaux dirigeants.</li></ol><h3 id="iv-pouvoir-de-supervision" tabindex="-1">(IV) Pouvoir de Supervision <a class="header-anchor" href="#iv-pouvoir-de-supervision" aria-label="Permalink to &quot;(IV) Pouvoir de Supervision&quot;">​</a></h3><p>L&#39;Assemblée Délibérante de l&#39;Ancre supervise les organes exécutif et judiciaire, notamment :</p><ol><li>Entendre et délibérer les rapports de travail.</li><li>Procédures d&#39;interpellation et de questionnement.</li><li>Commissions d&#39;enquête spéciales.</li><li>Vote de défiance envers le comité exécutif (conformément à la loi).</li></ol><h2 id="iv-le-comite-executif-symbiotique-pouvoir-executif" tabindex="-1">IV. Le Comité Exécutif Symbiotique (Pouvoir Exécutif) <a class="header-anchor" href="#iv-le-comite-executif-symbiotique-pouvoir-executif" aria-label="Permalink to &quot;IV. Le Comité Exécutif Symbiotique (Pouvoir Exécutif)&quot;">​</a></h2><h3 id="i-structure-organisationnelle" tabindex="-1">(I) Structure Organisationnelle <a class="header-anchor" href="#i-structure-organisationnelle" aria-label="Permalink to &quot;(I) Structure Organisationnelle&quot;">​</a></h3><p>Le Comité Exécutif Symbiotique est l&#39;organe exécutif suprême de l&#39;Univers Hengyuan, composé du Chef exécutif et des chefs de départements. Le Chef exécutif est élu par l&#39;Assemblée Délibérante de l&#39;Ancre et nommé après confirmation.</p><h3 id="ii-fonctions-administratives" tabindex="-1">(II) Fonctions Administratives <a class="header-anchor" href="#ii-fonctions-administratives" aria-label="Permalink to &quot;(II) Fonctions Administratives&quot;">​</a></h3><p>Le Comité Exécutif Symbiotique exerce les fonctions suivantes :</p><ol><li>Mettre en œuvre les lois et les résolutions de l&#39;Assemblée Délibérante de l&#39;Ancre.</li><li>Gérer les affaires économiques, sociales, culturelles, éducatives, médicales et de culture.</li><li>Formuler des règlements administratifs et des politiques.</li><li>Gérer les ressources publiques et le fonds d&#39;accumulation publique.</li><li>Traiter les affaires diplomatiques avec d&#39;autres univers.</li></ol><h3 id="iii-contraintes-du-pouvoir" tabindex="-1">(III) Contraintes du Pouvoir <a class="header-anchor" href="#iii-contraintes-du-pouvoir" aria-label="Permalink to &quot;(III) Contraintes du Pouvoir&quot;">​</a></h3><p>Le pouvoir du Comité Exécutif Symbiotique est soumis aux contraintes suivantes :</p><ol><li>Les décisions majeures doivent être soumises à l&#39;examen de l&#39;Assemblée Délibérante de l&#39;Ancre.</li><li>Les règlements administratifs ne doivent pas contrevenir aux lois.</li><li>Les actes administratifs sont soumis au contrôle juridictionnel du Tribunal Symbiotique.</li><li>L&#39;exercice du pouvoir administratif est supervisé par le Comité de Supervision de l&#39;Ancre.</li></ol><h2 id="v-le-tribunal-symbiotique-pouvoir-judiciaire" tabindex="-1">V. Le Tribunal Symbiotique (Pouvoir Judiciaire) <a class="header-anchor" href="#v-le-tribunal-symbiotique-pouvoir-judiciaire" aria-label="Permalink to &quot;V. Le Tribunal Symbiotique (Pouvoir Judiciaire)&quot;">​</a></h2><p>Le Tribunal Symbiotique est l&#39;organe judiciaire suprême de l&#39;Univers Hengyuan, exerçant le pouvoir d&#39;adjudication de manière indépendante. Ses fonctions fondamentales comprennent :</p><ol><li>Adjuger les affaires civiles, pénales, administratives et de culture.</li><li>Adjuger les affaires constitutionnelles et exercer le contrôle de constitutionnalité.</li><li>Exercer le pouvoir d&#39;interprétation unifiée du droit.</li><li>Exécuter les jugements et sauvegarder l&#39;autorité de l&#39;État de droit.</li></ol><p>L&#39;indépendance du Tribunal Symbiotique est garantie par la constitution et les lois ; les juges jouissent d&#39;un mandat à vie et ne peuvent être remplacés à volonté pendant leur mandat. Le pouvoir judiciaire est soumis à la supervision de l&#39;Assemblée Délibérante de l&#39;Ancre et du Comité de Supervision de l&#39;Ancre, mais aucun organe ne peut interférer avec l&#39;adjudication indépendante des cas individuels.</p><h2 id="vi-le-comite-de-supervision-de-l-ancre-pouvoir-de-supervision" tabindex="-1">VI. Le Comité de Supervision de l&#39;Ancre (Pouvoir de Supervision) <a class="header-anchor" href="#vi-le-comite-de-supervision-de-l-ancre-pouvoir-de-supervision" aria-label="Permalink to &quot;VI. Le Comité de Supervision de l&#39;Ancre (Pouvoir de Supervision)&quot;">​</a></h2><h3 id="i-etablissement-et-mandat" tabindex="-1">(I) Établissement et Mandat <a class="header-anchor" href="#i-etablissement-et-mandat" aria-label="Permalink to &quot;(I) Établissement et Mandat&quot;">​</a></h3><p>Le Comité de Supervision de l&#39;Ancre est l&#39;organe de supervision suprême de l&#39;Univers Hengyuan, établi conformément à la constitution, avec le pouvoir de superviser tous les organes de gouvernance et les fonctionnaires publics.</p><h3 id="ii-fonctions-de-supervision" tabindex="-1">(II) Fonctions de Supervision <a class="header-anchor" href="#ii-fonctions-de-supervision" aria-label="Permalink to &quot;(II) Fonctions de Supervision&quot;">​</a></h3><p>Le Comité de Supervision de l&#39;Ancre exerce les fonctions suivantes :</p><ol><li>Superviser l&#39;application et le respect des lois par tous les organes de gouvernance.</li><li>Enquêter et traiter la corruption, la négligence des devoirs et l&#39;abus de pouvoir.</li><li>Superviser l&#39;utilisation des ressources publiques et du fonds d&#39;accumulation publique.</li><li>Recevoir les plaintes et les rapports de toutes les vies et les classer pour enquête.</li><li>Soumettre des rapports de supervision à l&#39;Assemblée Délibérante de l&#39;Ancre.</li></ol><h3 id="iii-garanties-procedurales" tabindex="-1">(III) Garanties Procédurales <a class="header-anchor" href="#iii-garanties-procedurales" aria-label="Permalink to &quot;(III) Garanties Procédurales&quot;">​</a></h3><p>La supervision du Comité de Supervision de l&#39;Ancre est régie par des procédures strictes : les enquêtes suivent les procédures légales ; les droits et intérêts des personnes enquêtées sont protégés ; les résultats de la supervision sont ouverts et transparents.</p><h2 id="vii-controles-et-equilibres-entre-les-pouvoirs" tabindex="-1">VII. Contrôles et Équilibres Entre les Pouvoirs <a class="header-anchor" href="#vii-controles-et-equilibres-entre-les-pouvoirs" aria-label="Permalink to &quot;VII. Contrôles et Équilibres Entre les Pouvoirs&quot;">​</a></h2><p>Les contrôles et équilibres entre les pouvoirs de gouvernance se manifestent dans :</p><table tabindex="0"><thead><tr><th>Pouvoir</th><th>Contrôlé par</th><th>Mécanisme d&#39;équilibre</th></tr></thead><tbody><tr><td>Pouvoir législatif (Assemblée Délibérante de l&#39;Ancre)</td><td>Veto exécutif, contrôle juridictionnel</td><td>L&#39;exécutif peut renvoyer les projets de loi avec objections ; le tribunal peut examiner les lois</td></tr><tr><td>Pouvoir exécutif (Comité Exécutif)</td><td>Examen législatif, contrôle juridictionnel, supervision</td><td>Les lois et budgets sont examinés par le législatif ; les actes administratifs sont examinés par les tribunaux ; supervision par l&#39;organe de supervision</td></tr><tr><td>Pouvoir judiciaire (Tribunal Symbiotique)</td><td>Examen législatif, supervision</td><td>Les juges sont nommés et révoqués par le législatif ; la discipline judiciaire est supervisée par l&#39;organe de supervision</td></tr><tr><td>Pouvoir de supervision (Comité de Supervision)</td><td>Examen législatif, contraintes procédurales</td><td>Le champ et les procédures de supervision sont prescrits par la loi ; le législatif supervise son fonctionnement</td></tr></tbody></table><h2 id="viii-participation-multiraciale-a-la-gouvernance" tabindex="-1">VIII. Participation Multiraciale à la Gouvernance <a class="header-anchor" href="#viii-participation-multiraciale-a-la-gouvernance" aria-label="Permalink to &quot;VIII. Participation Multiraciale à la Gouvernance&quot;">​</a></h2><p>Le cadre de gouvernance garantit la participation de toutes les races par les canaux suivants :</p><ol><li><strong>Conseils de représentants raciaux</strong> : chaque race établit un conseil de représentants raciaux, élisant des représentants pour participer à l&#39;Assemblée Délibérante de l&#39;Ancre.</li><li><strong>Représentation proportionnelle</strong> : la répartition des sièges de l&#39;Assemblée Délibérante de l&#39;Ancre garantit la représentation des races majeures et la représentation de base des races minoritaires.</li><li><strong>Mécanisme de veto racial</strong> : pour la législation impliquant les intérêts vitaux d&#39;une race particulière, le conseil de représentants raciaux peut exercer un veto racial ; une procédure de vote spéciale est requise pour le surmonter.</li><li><strong>Gouvernance consultative</strong> : les affaires des races spéciales sont gouvernées par consultation avec les races concernées.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le <em>Cadre de Gouvernance et Équilibre des Pouvoirs</em> est le noyau institutionnel de la gouvernance par l&#39;État de droit de la Civilisation Symbiotique de l&#39;Ancre. En établissant la structure de gouvernance de la « séparation et équilibre des trois pouvoirs », l&#39;institution de supervision sur tout le processus et le mécanisme de participation multiraciale, il garantit le fonctionnement légal, équitable et transparent du pouvoir public, empêche l&#39;abus et la corruption du pouvoir, et fournit des garanties institutionnelles pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanisme d&#39;Adjudication)</li><li>30-锚点议事会职能与议事规则 (Fonctions et Règles de Procédure de l&#39;Assemblée Délibérante de l&#39;Ancre)</li><li>31-共生执行委员会职能与运行机制 (Fonctions et Mécanisme de Fonctionnement du Comité Exécutif Symbiotique)</li><li>32-锚点监督委员会职能与监察机制 (Fonctions et Mécanisme de Supervision du Comité de Supervision de l&#39;Ancre)</li></ul>',53)])])}const m=i(s,[["render",n]]);export{v as __pageData,m as default};
